# ! [doc = " Code for efficiently counting the number of `char`s in a UTF-8 encoded"] # ! [doc = " string."] # ! [doc = ""] # ! [doc = " Broadly, UTF-8 encodes `char`s as a \"leading\" byte which begins the `char`,"] # ! [doc = " followed by some number (possibly 0) of continuation bytes."] # ! [doc = ""] # ! [doc = " The leading byte can have a number of bit-patterns (with the specific"] # ! [doc = " pattern indicating how many continuation bytes follow), but the continuation"] # ! [doc = " bytes are always in the format `0b10XX_XXXX` (where the `X`s can take any"] # ! [doc = " value). That is, the most significant bit is set, and the second most"] # ! [doc = " significant bit is unset."] # ! [doc = ""] # ! [doc = " To count the number of characters, we can just count the number of bytes in"] # ! [doc = " the string which are not continuation bytes, which can be done many bytes at"] # ! [doc = " a time fairly easily."] # ! [doc = ""] # ! [doc = " Note: Because the term \"leading byte\" can sometimes be ambiguous (for"] # ! [doc = " example, it could also refer to the first byte of a slice), we'll often use"] # ! [doc = " the term \"non-continuation byte\" to refer to these bytes in the code."] use split_decls_genesis :: ourprelude :: * ; use core :: intrinsics :: unlikely ; const USIZE_SIZE : usize = size_of :: < usize > () ; const UNROLL_INNER : usize = 4 ; #[inline] pub (super) fn count_chars (s : & str) -> usize { if cfg ! (feature = "optimize_for_size") || s . len () < USIZE_SIZE * UNROLL_INNER { char_count_general_case (s . as_bytes ()) } else { do_count_chars (s) } } fn do_count_chars (s : & str) -> usize { const CHUNK_SIZE : usize = 192 ; const _ : () = assert ! (CHUNK_SIZE < 256) ; const _ : () = assert ! (CHUNK_SIZE . is_multiple_of (UNROLL_INNER)) ; let (head , body , tail) = unsafe { s . as_bytes () . align_to :: < usize > () } ; if unlikely (body . is_empty () || head . len () > USIZE_SIZE || tail . len () > USIZE_SIZE) { return char_count_general_case (s . as_bytes ()) ; } let mut total = char_count_general_case (head) + char_count_general_case (tail) ; for chunk in body . chunks (CHUNK_SIZE) { let mut counts = 0 ; let (unrolled_chunks , remainder) = chunk . as_chunks :: < UNROLL_INNER > () ; for unrolled in unrolled_chunks { for & word in unrolled { counts += contains_non_continuation_byte (word) ; } } total += sum_bytes_in_usize (counts) ; if ! remainder . is_empty () { let mut counts = 0 ; for & word in remainder { counts += contains_non_continuation_byte (word) ; } total += sum_bytes_in_usize (counts) ; break ; } } total } #[inline] fn contains_non_continuation_byte (w : usize) -> usize { const LSB : usize = usize :: repeat_u8 (0x01) ; ((! w >> 7) | (w >> 6)) & LSB } #[inline] fn sum_bytes_in_usize (values : usize) -> usize { const LSB_SHORTS : usize = usize :: repeat_u16 (0x0001) ; const SKIP_BYTES : usize = usize :: repeat_u16 (0x00ff) ; let pair_sum : usize = (values & SKIP_BYTES) + ((values >> 8) & SKIP_BYTES) ; pair_sum . wrapping_mul (LSB_SHORTS) >> ((USIZE_SIZE - 2) * 8) } fn char_count_general_case (s : & [u8]) -> usize { s . iter () . filter (| & & byte | ! super :: validations :: utf8_is_cont_byte (byte)) . count () }